-- =====================================================================
-- 470 Exception ID: per-organization sequential E-001 on
--     exception_request
--
-- SIR'S INSTRUCTION
-- ------------------
--   Exceptions must carry a per-organization unique id in the format
--   E-001 (E- + 3-digit sequential number), restarting at 001 per
--   organization, generated by the backend, and shown as a column in
--   the Exception Centre grid. Same shape as Risk's R-001 (378) and
--   Gap's G-001 (469).
--
-- WHY A TRIGGER (same reasoning as 469)
-- -------------------------------------
--   exception_request is inserted from several live procedures --
--   sp_exception_request_create, sp_sla_override_request_create,
--   sp_task_sla_extension_request_create -- with no shared choke point.
--   One AFTER INSERT trigger numbers every row on every path, present
--   and future, rather than re-issuing each create proc verbatim.
--   Every exception_request row (regular exception, SLA override, task
--   SLA extension) shares the one E- sequence, since they share the
--   table and the uniqueness rule.
--
-- NUMBERING
-- ---------
--   Identical mechanism to 469: MAX+1 per org under UPDLOCK/HOLDLOCK,
--   FORMAT(@n,'000'), NULLable column filled synchronously by the
--   trigger, filtered unique index as the backstop.
--
-- Idempotent / safe to re-run. ASCII-only.
-- DEPENDS ON: 161 (exception_request table).
-- Rollback: 470_exception_number_per_org_sequential_rollback.sql
-- =====================================================================
SET NOCOUNT ON;
GO

IF OBJECT_ID('grac_practice.exception_request','U') IS NULL
BEGIN
    RAISERROR('470: grac_practice.exception_request missing. Run 161 first.', 16, 1);
    SET NOEXEC ON;
END
GO

-- ---------------------------------------------------------------------
-- 1. Column
-- ---------------------------------------------------------------------
IF COL_LENGTH('grac_practice.exception_request','exception_number') IS NULL
    ALTER TABLE grac_practice.exception_request ADD exception_number NVARCHAR(20) NULL;
GO

-- ---------------------------------------------------------------------
-- 2. Backfill existing rows -- per organization, creation order.
-- ---------------------------------------------------------------------
;WITH ranked AS (
    SELECT exception_request_id, exception_number,
           ROW_NUMBER() OVER (PARTITION BY organization_id
                              ORDER BY exception_request_id) AS rn
    FROM   grac_practice.exception_request
    WHERE  exception_number IS NULL
)
UPDATE ranked
   SET exception_number = N'E-' + FORMAT(rn, '000');
PRINT '470: exception_request.exception_number backfilled = ' + CAST(@@ROWCOUNT AS NVARCHAR(20));
GO

-- ---------------------------------------------------------------------
-- 3. Filtered unique index (per org, over populated numbers only).
-- ---------------------------------------------------------------------
IF NOT EXISTS (SELECT 1 FROM sys.indexes
               WHERE name = 'uq_pm_exception_request_number'
                 AND object_id = OBJECT_ID('grac_practice.exception_request'))
    CREATE UNIQUE INDEX uq_pm_exception_request_number
        ON grac_practice.exception_request(organization_id, exception_number)
        WHERE exception_number IS NOT NULL;
GO

-- ---------------------------------------------------------------------
-- 4. AFTER INSERT trigger -- assign the next per-org E-nnn on insert.
-- ---------------------------------------------------------------------
CREATE OR ALTER TRIGGER grac_practice.trg_pm_exception_request_assign_number
ON grac_practice.exception_request
AFTER INSERT
AS
BEGIN
    SET NOCOUNT ON;
    IF NOT EXISTS (SELECT 1 FROM inserted WHERE exception_number IS NULL)
        RETURN;

    ;WITH to_number AS (
        SELECT i.exception_request_id, i.organization_id,
               ROW_NUMBER() OVER (PARTITION BY i.organization_id
                                  ORDER BY i.exception_request_id) AS rn
        FROM   inserted i
        WHERE  i.exception_number IS NULL
    ),
    base AS (
        SELECT d.organization_id,
               ISNULL(MAX(TRY_CONVERT(INT, SUBSTRING(e.exception_number, 3, 20))), 0) AS max_no
        FROM   (SELECT DISTINCT organization_id FROM to_number) d
        LEFT   JOIN grac_practice.exception_request e WITH (UPDLOCK, HOLDLOCK)
               ON  e.organization_id = d.organization_id
               AND e.exception_number LIKE N'E-%'
               AND TRY_CONVERT(INT, SUBSTRING(e.exception_number, 3, 20)) IS NOT NULL
        GROUP BY d.organization_id
    )
    UPDATE e
       SET exception_number = N'E-' + FORMAT(b.max_no + tn.rn, '000')
    FROM   grac_practice.exception_request e
    JOIN   to_number tn ON tn.exception_request_id = e.exception_request_id
    JOIN   base b       ON b.organization_id = tn.organization_id;
END
GO

PRINT '470 complete: exception_request.exception_number (E-001 per organization) added, backfilled, indexed, and auto-assigned on insert.';
GO
SET NOEXEC OFF;
GO
